CREATE TABLE IF NOT EXISTS licenses (
  id INT AUTO_INCREMENT PRIMARY KEY, license_key VARCHAR(20) NOT NULL UNIQUE, hwid VARCHAR(128) NULL, owner VARCHAR(120) NULL,
  status ENUM('active','revoked') DEFAULT 'active', activated_at DATETIME NULL, expires_at DATETIME NULL, duration_days INT DEFAULT 365,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS threat_versions (
  id INT AUTO_INCREMENT PRIMARY KEY, version VARCHAR(20) NOT NULL UNIQUE, yara MEDIUMTEXT, hashes MEDIUMTEXT, domains MEDIUMTEXT, sig TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS malware_hashes (hash VARCHAR(64) PRIMARY KEY, name VARCHAR(120), added_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS blocked_domains (domain VARCHAR(253) PRIMARY KEY, added_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS alerts (id INT AUTO_INCREMENT PRIMARY KEY, hwid VARCHAR(128), type VARCHAR(40), payload TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rate_limit (id BIGINT AUTO_INCREMENT PRIMARY KEY, k VARCHAR(40), ip VARCHAR(45), ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(k,ip,ts));
